var key = utils.getSelectFieldKey(form.components,instance.component.parentKey);
var selectFieldValue = utils.findValueGivenAKey(data,key); 
var currentPreActivityValue = utils.getValueFromDataItemMappingKeyValuePair(instance.component.activityType+key);
if(currentPreActivityValue === "not found"){
  utils.addToDataItemMappingKeyValuePair(instance.component.activityType+key, selectFieldValue);
  if(!utils.isEmptyString(selectFieldValue)){
    result = true;
  }
  else{
    result = false;
  }
}
else{
  if(!utils.isEmptyString(selectFieldValue) && currentPreActivityValue !== selectFieldValue){
         utils.updateDataItemMappingKeyValuePair(instance.component.activityType+key,selectFieldValue);
     result = true;
  }else{
    result = false;
  }
}

actions.value:
var key = utils.getSelectFieldKey(form.components,instance.component.parentKey);
var selectFieldValue = utils.findValueGivenAKey(data,key);
if(utils.getValueFromDataItemMappingKeyValuePair('postActivity'+key) !== selectFieldValue){
 var postKey = instance.component.parentKey+"_postActivity";
utils.setValueGivenAKey(data,postKey,undefined);
}

utils.getFieldsForDataItemMapping(selectFieldValue,instance.component.key, instance.component.activityType).then((data)=>
{
 instance.setFieldValue(data);       
}).catch((error)=>
{
  var temp = [ {
       "preActivity_SourceExpression": "",
       "preActivity_TargetFormField": "",
       "preActivity_DataType": ""
  }];

 instance.setFieldValue(temp); console.error(error);
});
